import React from 'react';
import axios from 'axios';

const AQIInputForm = ({ features, setFeatures, setResult }) => {
  const handleChange = (e) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handlePredict = async () => {
    try {
      const response = await axios.post('http://localhost:5000/predict', {
        'PM2.5': features.PM2_5,
        'CO': features.CO,
        'NO2': features.NO2,
        'NH3': features.NH3,
        'O3': features.O3,
        'Temp': features.Temp,
        'Humidity': features.Humidity,
        'Pressure': features.Pressure
      });
      setResult(response.data.prediction);
    } catch (err) {
      console.error(err);
      setResult('Error connecting to server');
    }
  };

  return (
    <div style={{ background: '#333', color: 'white', padding: '20px', borderRadius: '10px' }}>
      <h3>🧪 Enter Sensor Readings</h3>
      {[
        { label: 'PM2.5', name: 'PM2_5', min: 0, max: 200 },
        { label: 'CO', name: 'CO', min: 0, max: 100 },
        { label: 'NO2', name: 'NO2', min: 0, max: 100 },
        { label: 'NH3', name: 'NH3', min: 0, max: 100 },
        { label: 'O3', name: 'O3', min: 0, max: 100 },
        { label: 'Temperature (°C)', name: 'Temp', min: 0, max: 50 },
        { label: 'Humidity (%)', name: 'Humidity', min: 0, max: 100 },
        { label: 'Pressure (hPa)', name: 'Pressure', min: 900, max: 1100 }
      ].map((item) => (
        <div key={item.name} style={{ marginBottom: '12px' }}>
          <label>{item.label}</label>
          <input
            type="range"
            name={item.name}
            min={item.min}
            max={item.max}
            value={features[item.name]}
            onChange={handleChange}
            style={{ width: '100%' }}
          />
          <div>{features[item.name].toFixed(1)}</div>
        </div>
      ))}

      <button
        onClick={handlePredict}
        style={{ marginTop: '15px', padding: '10px 20px', backgroundColor: '#03a9f4', color: 'white', border: 'none', borderRadius: '6px' }}
      >
        Predict AQI
      </button>
    </div>
  );
};

export default AQIInputForm;
